package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.math.*;
import java.time.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import tools.jackson.databind.ObjectMapper;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.shared.ApiException;
import com.mavric.health.patients.domain.Requests.Patient;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Offline executor double and modeled manager; no clinical rules or connected persistence. */
class SqlServerPatientStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",PATIENT="cc000000-0000-4000-8000-000000000001",TIME="2026-11-04T00:00:00.123456Z";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final ObjectMapper mapper=new ObjectMapper();final SqlServerPatientStore store=new SqlServerPatientStore(executor,manager,mapper);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/patients");final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
 SqlServerPatientStoreTest(){actor("ADM","HUMAN","ACTIVE",List.of("CORE"));when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());calls.add(inv.getArgument(0));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void actor(String role,String domain,String status,List<String> modules){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of(role),"a".repeat(64)));request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic",domain.equals("ANIMAL")?"VETERINARY":"DOCTOR",domain,status,modules));}
 static Map<String,Object> patient(){var r=new LinkedHashMap<String,Object>();r.put("id",PATIENT);r.put("tenantId",TENANT);r.put("name","Synthetic patient");r.put("domain","HUMAN");r.put("identifier","SYN-001");r.put("birthDate",null);r.put("species",null);r.put("contact",new LinkedHashMap<String,Object>());r.put("allergies",new ArrayList<>(List.of("synthetic")));r.put("revision",1);r.put("createdAt",TIME);return r;}
 static Patient input(){return new Patient("Synthetic \u4e2d\uD83E\uDDB7","HUMAN","SYN-001",null,null,new LinkedHashMap<>(),new LinkedHashSet<>(List.of("synthetic")));}
 static Patient change(String key,Object value){try{var p=input();var cs=p.getClass().getRecordComponents();var types=new Class<?>[cs.length];var a=new Object[cs.length];for(int i=0;i<cs.length;i++){types[i]=cs[i].getType();a[i]=cs[i].getName().equals(key)?value:cs[i].getAccessor().invoke(p);}return (Patient)p.getClass().getDeclaredConstructor(types).newInstance(a);}catch(Exception e){throw new AssertionError(e);}}
 void rows(List<Map<String,Object>> rows){results.add(new SqlServerExecutor.Result(List.of(rows),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var e=assertThrows(ApiException.class,work::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());}
 void saves(Patient input){doAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.PATIENT_SAVE,inv.getArgument(0));var c=inv.<SqlServerContext>getArgument(1);assertEquals(TENANT,c.tenantId());assertEquals(ID,c.actorId());assertEquals(SqlServerContext.Scope.REQUEST,c.scope());Object[] a=(Object[])inv.getRawArguments()[2];calls.add(inv.getArgument(0));args.add(Arrays.asList(a.clone()));var json=mapper.readValue((String)a[1],Map.class);assertEquals(Set.of("name","domain","identifier","birthDate","species","contact","allergies"),json.keySet());assertEquals(input.name(),json.get("name"));assertEquals(input.birthDate()==null?null:input.birthDate().toString(),json.get("birthDate"));var row=patient();row.put("id",a[0]);row.put("domain",input.domain());row.put("name",input.name());row.put("identifier",input.identifier());row.put("birthDate",input.birthDate()==null?null:input.birthDate().toString());row.put("species",input.species());row.put("contact",input.contact());row.put("allergies",new ArrayList<>(input.allergies()));row.put("revision",(Integer)a[2]==0?1:8);row.put("passwordHash","private");return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());}).when(executor).execute(any(),any(),any(Object[].class));}
 @Test void listAndGetExactBindsClampingQueryBoundaryAndNoBranchFilter(){rows(List.of(patient()));assertEquals(11,store.list(request,null,0,-1).getFirst().size());assertEquals(List.of("",1,0),args.getFirst());rows(List.of());store.list(request,"%[_]",999,Integer.MAX_VALUE);assertEquals(List.of("%[_]",200,Integer.MAX_VALUE),args.getLast());rows(List.of());store.list(request,"x".repeat(3998),1,0);assertEquals(3998,((String)args.getLast().getFirst()).length());assertEquals(400,assertThrows(ApiException.class,()->store.list(request,"x".repeat(3999),1,0)).status);rows(List.of(patient()));assertEquals(PATIENT,store.get(request,PATIENT).get("id"));assertEquals(List.of(PATIENT),args.getLast());assertEquals(List.of(SqlServerProcedure.PATIENTS_LIST,SqlServerProcedure.PATIENTS_LIST,SqlServerProcedure.PATIENTS_LIST,SqlServerProcedure.PATIENT_GET),calls);}
 @Test void projectionNullableJsonMaxPrecisionExtrasAndDeepImmutability(){var row=patient();var nested=new ArrayList<>(Arrays.asList(null,new BigDecimal("12345678901234567890.123456"),"\u4e2d\uD83E\uDDB7".repeat(2000)));var contact=new LinkedHashMap<String,Object>();contact.put("nested",nested);contact.put("null",null);row.put("contact",contact);row.put("secret","private");rows(List.of(row));var out=store.get(request,PATIENT);assertEquals(11,out.size());assertTrue(out.containsKey("birthDate"));assertNull(out.get("birthDate"));assertNull(out.get("species"));assertFalse(out.toString().contains("private"));var values=(List<?>)((Map<?,?>)out.get("contact")).get("nested");assertEquals(nested,values);nested.clear();assertEquals(3,values.size());assertThrows(UnsupportedOperationException.class,values::clear);assertThrows(UnsupportedOperationException.class,((Map<?,?>)out.get("contact"))::clear);assertThrows(UnsupportedOperationException.class,((List<?>)out.get("allergies"))::clear);assertThrows(UnsupportedOperationException.class,out::clear);}
 @Test void saveCreateUpdateExpectedAndSingleSpWhitelistNullsDatesAndUnicode(){var contact=new LinkedHashMap<String,Object>();contact.put("large","\u4e2d\uD83E\uDDB7".repeat(2000));contact.put("decimal",new BigDecimal("12345678901234567890.123456"));contact.put("null",null);var input=change("contact",contact);saves(input);var created=store.save(request,null,input,0);assertEquals(1,created.get("revision"));assertEquals(UUID.fromString((String)created.get("id")).toString(),created.get("id"));assertEquals(0,args.getFirst().get(2));assertTrue(((String)args.getFirst().get(1)).contains("12345678901234567890.123456"));assertEquals(11,store.save(request,PATIENT,input,7).size());assertEquals(7,args.getLast().get(2));assertEquals(8,store.save(request,PATIENT,input,7).get("revision"));assertTrue(calls.stream().allMatch(p->p==SqlServerProcedure.PATIENT_SAVE));assertEquals(3,calls.size());assertFalse(created.toString().contains("private"));var dated=change("birthDate",LocalDate.of(2000,2,29));saves(dated);store.save(request,PATIENT,dated,7);assertEquals("2000-02-29",mapper.readValue((String)args.getLast().get(1),Map.class).get("birthDate"));}
 @Test void animalRequiresSpeciesAndUsesSameTypedSave(){actor("REC","ANIMAL","ACTIVE",List.of("CORE"));var animal=new Patient("Synthetic animal","ANIMAL","SYN-ANIMAL",null,"synthetic-species",Map.of(),Set.of());saves(animal);assertEquals("ANIMAL",store.save(request,null,animal,0).get("domain"));assertEquals("synthetic-species",store.save(request,null,animal,0).get("species"));var missing=new Patient("Synthetic animal","ANIMAL","SYN-ANIMAL",null,null,Map.of(),Set.of());assertEquals(400,assertThrows(ApiException.class,()->store.save(request,null,missing,0)).status);assertEquals(2,calls.size());}
 @Test void invalidPatientFieldsAndExpectedPairsRejectBeforeSp(){var cases=new LinkedHashMap<String,List<Object>>();cases.put("name",Arrays.asList(null," ","x".repeat(161),"\uD83E\uDDB7".repeat(81)));cases.put("domain",Arrays.asList(null,"ANIMAL","human"));cases.put("identifier",Arrays.asList(null," ","x".repeat(101)));cases.put("species",List.of("x".repeat(81)));cases.put("birthDate",List.of(LocalDate.now(ZoneOffset.UTC).plusDays(2),LocalDate.of(0,1,1),LocalDate.of(10000,1,1)));cases.put("contact",Arrays.asList((Object)null));cases.put("allergies",Arrays.asList(null,Set.of("x".repeat(161)),Set.of(1),new HashSet<>(Arrays.asList("synthetic",null))));for(var entry:cases.entrySet())for(Object value:entry.getValue()){var input=change(entry.getKey(),value);assertEquals(400,assertThrows(ApiException.class,()->store.save(request,null,input,0)).status,entry.getKey());}assertEquals(400,assertThrows(ApiException.class,()->store.save(request,null,null,0)).status);assertEquals(400,assertThrows(ApiException.class,()->store.save(request,null,input(),1)).status);assertEquals(400,assertThrows(ApiException.class,()->store.save(request,PATIENT,input(),0)).status);assertEquals(400,assertThrows(ApiException.class,()->store.save(request,PATIENT,input(),-1)).status);assertEquals(400,assertThrows(ApiException.class,()->store.save(request,"bad",input(),1)).status);verifyNoInteractions(executor);}
 static Map<String,Object> depth(int count){Object value="leaf";for(int i=0;i<count;i++)value=Map.of("v",value);return (Map<String,Object>)value;}
 @Test void invalidJsonCyclesNaNTypesDepthAndLengthAreSafe400BeforeSp(){var cycle=new LinkedHashMap<String,Object>();cycle.put("self",cycle);var list=new ArrayList<>();list.add(list);var badKey=new LinkedHashMap<Object,Object>();badKey.put(1,"bad");for(Map<?,?> contact:List.of(cycle,Map.of("v",list),Map.of("v",Double.NaN),Map.of("v",Double.POSITIVE_INFINITY),Map.of("v",new Object()),badKey,depth(31),Map.of("v","x".repeat(200000)))){var input=change("contact",contact);var e=assertThrows(ApiException.class,()->store.save(request,null,input,0));assertEquals(400,e.status);assertFalse(e.toString().contains("leaf"));assertNull(e.getCause());}verifyNoInteractions(executor);}
 @Test void contactLengthAndDepthExactBoundaryPreserveCompleteText(){int overhead=mapper.writeValueAsString(Map.of("v","")).length();var boundary=change("contact",Map.of("v","x".repeat(200000-overhead)));saves(boundary);store.save(request,null,boundary,0);assertEquals(200000-overhead,((String)((Map<?,?>)mapper.readValue((String)args.getLast().get(1),Map.class).get("contact")).get("v")).length());var nested=change("contact",depth(30));saves(nested);assertEquals(11,store.save(request,null,nested,0).size());}
 @Test void get404CardinalityForeignIdentityAndAllColumnsTypesFailClosed(){rows(List.of());assertEquals(404,assertThrows(ApiException.class,()->store.get(request,PATIENT)).status);for(String key:patient().keySet()){var row=patient();row.remove(key);rows(List.of(row));safe(()->store.get(request,PATIENT));}for(var bad:List.of(Map.entry("id",ID),Map.entry("tenantId",ID),Map.entry("domain","ANIMAL"),Map.entry("birthDate","2027-02-29"),Map.entry("birthDate",LocalDate.of(2000,1,1)),Map.entry("species",1),Map.entry("revision",1L),Map.entry("revision",0),Map.entry("createdAt","2026-11-04T00:00:00.123456789Z"),Map.entry("contact",List.of()),Map.entry("allergies",List.of(1)))){var row=patient();row.put(bad.getKey(),bad.getValue());rows(List.of(row));safe(()->store.get(request,PATIENT));}rows(List.of(patient(),patient()));safe(()->store.get(request,PATIENT));rows(List.of(patient(),patient()));safe(()->store.list(request,"",1,0));results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.get(request,PATIENT));results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));safe(()->store.list(request,"",1,0));}
 @Test void directRoleHostTokenUuidAndWriteStateModuleAreRevalidated(){actor("AUD","HUMAN","ACTIVE",List.of("CORE"));assertEquals(403,assertThrows(ApiException.class,()->store.save(request,null,input(),0)).status);actor("ADM","HUMAN","SUSPENDED",List.of("CORE"));assertEquals("SUSPENDED",assertThrows(ApiException.class,()->store.save(request,null,input(),0)).code);actor("ADM","HUMAN","ACTIVE",List.of());assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->store.save(request,null,input(),0)).code);actor("ADM","HUMAN","ACTIVE",List.of("CORE"));request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of("SAD","PRO"),"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,()->store.list(request,"",1,0)).status);request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",TENANT,List.of("ADM"),"bad"));safe(()->store.get(request,PATIENT));request.setAttribute("health.tenant","bad");safe(()->store.get(request,PATIENT));safe(()->store.get(null,PATIENT));verifyNoInteractions(executor);}
 @Test void saveMappingCommitOuterRollbackAndVendorErrorsNeverRetry(){rows(List.of());safe(()->store.save(request,PATIENT,input(),1));var wrong=patient();wrong.put("id",ID);rows(List.of(wrong));safe(()->store.save(request,PATIENT,input(),1));rows(List.of(patient()));manager.failCommit=true;safe(()->store.save(request,PATIENT,input(),1));rows(List.of(patient()));assertThrows(RuntimeException.class,()->manager.outer(()->{store.save(request,PATIENT,input(),1);assertFalse(manager.events.getLast().equals("commit"));throw new RuntimeException("cancel");}));assertEquals("rollback",manager.events.getLast());for(int code:List.of(51002,51003,51004,51005)){doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,code))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->store.save(request,PATIENT,input(),1));assertEquals(Map.of(51002,404,51003,409,51004,403,51005,409).get(code),e.status);assertFalse(e.toString().contains("private"));}verify(executor,times(8)).execute(eq(SqlServerProcedure.PATIENT_SAVE),any(),any(Object[].class));}

 @Test void malformedOutputJsonAndUnexpectedMapperFailureAreSafe500(){var cycle=new LinkedHashMap<String,Object>();cycle.put("self",cycle);for(Object contact:List.of(cycle,Map.of("number",Double.NaN))){var row=patient();row.put("contact",contact);rows(List.of(row));safe(()->store.get(request,PATIENT));}for(String key:patient().keySet()){if(List.of("birthDate","species").contains(key))continue;var row=patient();row.put(key,null);rows(List.of(row));safe(()->store.get(request,PATIENT));}var broken=mock(ObjectMapper.class);doThrow(new IllegalStateException("private mapper canary")).when(broken).writeValueAsString(any());int callsBefore=calls.size();var alternate=new SqlServerPatientStore(executor,manager,broken);var e=assertThrows(ApiException.class,()->alternate.save(request,null,input(),0));assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertFalse(e.toString().contains("private"));assertNull(e.getCause());assertEquals(callsBefore,calls.size());assertEquals("rollback",manager.events.getLast());}
}
